import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as e,o as r,c as o,a2 as d}from"./chunks/framework.CHeM0PsO.js";const P=JSON.parse('{"title":"swag2mcp","description":"","frontmatter":{},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md","lastUpdated":1784903584000}'),s={name:"ja/index.md"};function n(i,t,l,p,c,h){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="swag2mcp" tabindex="-1">swag2mcp <a class="header-anchor" href="#swag2mcp" aria-label="Permalink to &quot;swag2mcp&quot;">​</a></h1><div style="background:#dc2626;color:white;padding:20px 24px;border-radius:12px;text-align:center;font-size:1.4em;font-weight:700;margin:24px 0;"> 🚧 作業中 — リリース準備中！ </div><p>OpenAPI/Swagger/Postman の API 仕様を、Model Context Protocol (MCP) を介して LLM エージェントと連携させます。</p><a href="https://www.youtube.com/watch?v=1Da4UmE2f9U" target="_blank"><img src="https://raw.githubusercontent.com/mmadfox/swag2mcp/main/docs/cover.png" alt="プレビュー"></a><h2 id="あなたの-api-が-llm-と対話" tabindex="-1">あなたの API が LLM と対話 <a class="header-anchor" href="#あなたの-api-が-llm-と対話" aria-label="Permalink to &quot;あなたの API が LLM と対話&quot;">​</a></h2><p>1 行の設定で、あらゆる OpenAPI/Swagger/Postman ファイルを MCP サーバーに変換します。LLM エージェントは API を発見、調査、呼び出し — 統合コードは一切不要です。</p><img src="'+a+'" width="700" alt="swag2mcp アーキテクチャ"><h2 id="ラッパーを書くのはもう終わり" tabindex="-1">ラッパーを書くのはもう終わり <a class="header-anchor" href="#ラッパーを書くのはもう終わり" aria-label="Permalink to &quot;ラッパーを書くのはもう終わり&quot;">​</a></h2><p>新しい API を LLM に接続するたびに、同じボイラープレート（仕様解析、認証、エラーハンドリング、レート制限）を書いていませんか？ swag2mcp が代わりに行います — 19 の既製 MCP ツールを提供。</p><h2 id="こんな方に" tabindex="-1">こんな方に <a class="header-anchor" href="#こんな方に" aria-label="Permalink to &quot;こんな方に&quot;">​</a></h2><table tabindex="0"><thead><tr><th>役割</th><th>理由</th></tr></thead><tbody><tr><td><strong>AI エージェント開発者</strong></td><td>2 日ではなく 2 分で API を接続</td></tr><tr><td><strong>MCP エンジニア</strong></td><td>ハンドラーコード不要 — 仕様を指定するだけ</td></tr><tr><td><strong>アーキテクト</strong></td><td>全 LLM 向けの単一 API 統合レイヤー</td></tr><tr><td><strong>データアナリスト</strong></td><td>自然言語で API にアクセス、コーディング不要</td></tr><tr><td><strong>DevOps / SRE</strong></td><td>追加サービスなしで LLM による監視と自動化</td></tr><tr><td><strong>インテグレーター</strong></td><td>9 つの認証方式を標準搭載 — Basic から OAuth2、HMAC まで</td></tr><tr><td><strong>QA エンジニア</strong></td><td>実際の API を使わずにモックサーバーで分離テスト</td></tr><tr><td><strong>プロダクトマネージャー</strong></td><td>バックエンド作業なしで迅速な AI 機能プロトタイプ</td></tr><tr><td><strong>その他多数</strong></td><td></td></tr></tbody></table><hr><h2 id="ライセンス" tabindex="-1">ライセンス <a class="header-anchor" href="#ライセンス" aria-label="Permalink to &quot;ライセンス&quot;">​</a></h2><p><strong>GNU Affero General Public License v3.0</strong> (AGPL v3) の下でライセンスされています。</p><p>全文は <a href="https://github.com/mmadfox/swag2mcp/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a> をご覧ください。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SPDX-License-Identifier: AGPL-3.0-only</span></span></code></pre></div>',16)])])}const b=e(s,[["render",n]]);export{P as __pageData,b as default};
